//! R9 live native opportunity gate. Public market data only; no trading.
use futures_util::{SinkExt,StreamExt};use serde_json::json;use spotarb_native_market_core::{owner_index,HistorySink,CoreError,Owner,RawFrame,Update,Venue};use std::{collections::{HashMap,HashSet},time::{Duration,Instant,SystemTime,UNIX_EPOCH}};use tokio_tungstenite::{connect_async,tungstenite::Message};
struct H{n:u64}impl HistorySink for H{fn accept(&mut self,_:&RawFrame,_:&Update)->Result<(),CoreError>{self.n+=1;Ok(())}}fn wall()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis()as i64}
#[tokio::main]async fn main(){let bases=std::env::var("R9_BASES").unwrap().split(',').map(str::to_string).collect::<Vec<_>>();let secs=std::env::var("R9_SECONDS").ok().and_then(|s|s.parse().ok()).unwrap_or(30);let start=Instant::now();let mut owners=(0..12).map(|i|Owner::new(i,12,800).unwrap()).collect::<Vec<_>>();let mut h=H{n:0};let mut sb=HashSet::new();let mut so=HashSet::new();let mut errors=0u64;
let streams=bases.iter().map(|x|format!("{}usdt@bookTicker",x.to_lowercase())).collect::<Vec<_>>().join("/");let(mut b,_)=connect_async(format!("wss://fstream.binance.com/stream?streams={streams}")).await.unwrap();let(mut o,_)=connect_async("wss://ws.okx.com:8443/ws/v5/public").await.unwrap();let args=bases.iter().map(|x|json!({"channel":"books5","instId":format!("{x}-USDT")})).collect::<Vec<_>>();o.send(Message::Text(json!({"op":"subscribe","args":args}).to_string())).await.unwrap();
while start.elapsed()<Duration::from_secs(secs){tokio::select!{x=b.next()=>if let Some(Ok(Message::Text(raw)))=x{let f=RawFrame{source:None,venue:Venue::BinanceFutures,epoch:1,received_ns:start.elapsed().as_nanos()as u64,received_wall_ms:wall(),raw};match spotarb_native_market_core::parse(&f){Ok(u)=>{sb.insert(u.base.clone());let i=owner_index(&u.base,12);if owners[i].ingest_parsed(&f,u,&mut h).is_err(){errors+=1}},Err(_)=>errors+=1}},x=o.next()=>if let Some(Ok(Message::Text(raw)))=x{if raw.contains("\"event\""){continue}let f=RawFrame{source:None,venue:Venue::OkxSpot,epoch:1,received_ns:start.elapsed().as_nanos()as u64,received_wall_ms:wall(),raw};match spotarb_native_market_core::parse(&f){Ok(u)=>{so.insert(u.base.clone());let i=owner_index(&u.base,12);if owners[i].ingest_parsed(&f,u,&mut h).is_err(){errors+=1}},Err(_)=>errors+=1}}}}
let now=start.elapsed().as_nanos()as u64;let mut paired=0;let mut reasons:HashMap<&str,u64>=HashMap::new();let mut best=(-1e99f64,String::new());for base in &bases{let i=owner_index(base,12);let(s,f)=owners[i].snapshot_pair(base);if let(Some(s),Some(f))=(s,f){paired+=1;let sa=(now-s.received_ns)as f64/1e6;let fa=(now-f.received_ns)as f64/1e6;let r=if sa>800.||fa>800.{"STALE_BOOK"}else if s.asks.is_empty()||f.bids.is_empty(){"SYSTEM_NOT_READY"}else{let gross=(f.bids[0].0/s.asks[0].0-1.)*10000.;if gross>best.0{best=(gross,base.clone())}if gross-20.>=42.{"EXECUTABLE_CANDIDATE"}else{"EDGE_TOO_LOW"}};*reasons.entry(r).or_default()+=1;}}
println!("{}",json!({"r9_live":errors==0&&paired==bases.len(),"requested":bases.len(),"binance_seen":sb.len(),"okx_seen":so.len(),"paired":paired,"updates":h.n,"errors":errors,"reasons":reasons,"best_gross_bps":best.0,"best_base":best.1,"cost_bps":20,"required_net_bps":42,"trading":false}));}